function storageKey(slug){return`${STORAGE_PREFIX}.${String(slug||'unknown')}.onboarding`}
function onboardingSeen(slug){try{return localStorage.getItem(storageKey(slug))==='done'}catch{return false}}
function rememberOnboarding(slug){try{localStorage.setItem(storageKey(slug),'done')}catch{}}
async function onboardingSeenPersistent(api,slug){
  try{
    const result=await api?.requestHostAction?.('ui.preference.get',{key:storageKey(slug)})
    if(result?.accepted!==false&&String(result?.value||'')==='done')return true
  }catch{}
  const localSeen=onboardingSeen(slug)
  if(localSeen)try{await api?.requestHostAction?.('ui.preference.set',{key:storageKey(slug),value:'done'})}catch{}
  return localSeen
}
async function rememberOnboardingPersistent(api,slug){
  rememberOnboarding(slug)
  try{await api?.requestHostAction?.('ui.preference.set',{key:storageKey(slug),value:'done'})}catch{}
  return true
}
function surfaceReview(){return String(location.pathname||'').includes('/surface-review/')||document.body?.dataset?.galleryMode}
function onboardingPolicy(){try{const value=new URLSearchParams(location.search).get('onboarding');return value==='0'?'never':value==='1'?'force':'first-run'}catch{return'first-run'}}
function normalizeGuideChapter(row,profile){if(Array.isArray(row))return{section:String(row[0]||'GUIDE'),title:String(row[1]||profile?.title||'GUIDE'),summary:String(row[2]||''),steps:[],controls:[],tips:[],links:[]};return{section:String(row?.section||'GUIDE'),title:String(row?.title||profile?.title||'GUIDE'),summary:String(row?.summary||''),steps:Array.isArray(row?.steps)?row.steps:[],controls:Array.isArray(row?.controls)?row.controls:[],tips:Array.isArray(row?.tips)?row.tips:[],links:Array.isArray(row?.links)?row.links:[]}}
function guideDepth(profile){const chapters=(profile?.chapters||[]).map(row=>normalizeGuideChapter(row,profile));return{chapters:chapters.length,steps:chapters.reduce((sum,row)=>sum+row.steps.length,0),controls:chapters.reduce((sum,row)=>sum+row.controls.length,0),tips:chapters.reduce((sum,row)=>sum+row.tips.length,0),links:chapters.reduce((sum,row)=>sum+row.links.length,0)}}

