  const dock=markReview(el('div','moog-guide-dock'),semanticReviewId(slug,'territory','guide')),assembly=el('div','moog-guide-button-assembly'),rendered=createTrambustissimoRoundPanelButton({tone:'charcoal'}),button=rendered.button
